private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb, byte lead) {
    int extraBytesToRead = leadingSigilToExtraBytes(lead);
    if (extraBytesToRead == 0) {
        return i + 1;
    } else {
        int codePoint = readUTF8Bytes(i, bb, extraBytesToRead);
        sb.appendCodePoint(codePoint);
        return i + extraBytesToRead + 1;
    }
}

private static int leadingSigilToExtraBytes(byte lead) {
    switch (lead >> 4) {
        case 0xC:
        case 0xD:
            return 1;
        case 0xE:
            return 2;
        case 0xF:
