                return -1;
            } else {
                return 3;
            }
        default:
            return 0;
    }
}

private static int readUTF8Bytes(int i, ByteBuffer bb, int numBytesToRead) {
    int codePoint = 0;
    for (int j = 0; j < numBytesToRead; j++) {
        int byteToAdd = bb.get(i + j);
        codePoint = (codePoint << 6) | byteToAdd;
    }
    return codePoint;
}

