private void enlarge(int size) {
    // Check if the current capacity of the byte vector is already sufficient
    if (size <= this.capacity) {
        return;
    }

    // Calculate the new capacity required to store 'size' more bytes
    int newCapacity = (size + this.capacity) * 2;

    // Create a new byte array with the new capacity
    byte[] newArray = new byte[newCapacity];

    // Copy the existing bytes to the new array
    System.arraycopy(this.data, 0, newArray, 0, this.data.length);

    // Set the new array as the current data of the byte vector
    this.data = newArray;
}

private void enlarge(final int size) {
    // Check if the current capacity is sufficient
    if (size + memory.length <= capacity) {
        // If the current capacity is sufficient, return
        return;
    }

    // Determine the new capacity
    int newCapacity = Math.max(memory.length * 2, size + memory.length);

    // Allocate the new memory
    byte[] newMemory = new byte[newCapacity];

    // Copy the existing memory to the new memory
    System.arraycopy(memory, 0, newMemory, 0, memory.length);

    // Set the new memory and capacity
    memory = newMemory;
    capacity = newCapacity;
}

