    final String formattedDate = DateTimeFormatter.ofPattern("dd.MM.yyyy").format(event.getDate());
    final String level = String.format("%5s", event.getLevel());
    final String logger = String.format("%-15.15s", event.getLoggerName());
    final String message = event.getMessage();
    return String.format(conversionPattern, formattedDate, level, logger, message);

