    if (nonEmptyBucketIndex < 0) {
        return;
    }
    Set<Integer> nonEmptyBucket = bucketsByLabel.get(nonEmptyBucketIndex);
    for (int vertex : nonEmptyBucket) {
        int label = labels.get(vertex);
        if (label > minLabel) {
            bucketsByLabel.get(minLabel).add(vertex);
        }
        bucketsByLabel.get(label).remove(vertex);
    }
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        Set<Integer> bucket = bucketsByLabel.get(i);
        if (bucket.size() == 0) {
            labels.set(i, -1);
        }
