private int readTag() throws IOException {

    int tag = 0;

    // Read a single byte
    int tagByte = this.readUnsignedByte();

    // If the tag byte is zero, we have reached EOF
    if (tagByte == 0) {
      return 0;
    }

    // Set the tag number using the protocol value
    tag = tagByte << TAG_FIELD_NUMBER_BITS;

    // Read the field number
    int fieldNumber = this.readVarint(TAG_FIELD_NUMBER_BITS);

    // Add the field number to the tag number
    tag += fieldNumber;

    return tag;
  }

