public List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

        // Create a new empty List to store the ThreadSnapshot objects
        List<ThreadSnapshot> threadSnapshots = new ArrayList<ThreadSnapshot>();
        // Create a new FileInputStream to read the file
        try (FileInputStream in = new FileInputStream(file)) {
            // Read the file line by line
            String line;
            while ((line = in.readLine()) != null) {
                // Parse the line to get the thread stack trace
                ThreadSnapshot threadSnapshot = parseThreadSnapshotFromLine(line);
                // Check if the thread snapshot is in the given time range
                if (threadSnapshot.getTimestamp() >= timeRanges.get(0).getStartTime() && threadSnapshot.getTimestamp() <= timeRanges.get(timeRanges.size() - 1).getEndTime()) {
                    // If the thread snapshot is in the time range, add it to the List
                    threadSnapshots.add(threadSnapshot);
                }
            }
        }
        // Return the List of ThreadSnapshots
        return threadSnapshots;
    }

    // This method parses a single line of the file and returns a ThreadSnapshot object
    private static ThreadSnapshot parseThreadSnapshotFromLine(String line) {
        // Initialize the ThreadSnapshot object
        ThreadSnapshot threadSnapshot = new ThreadSnapshot();
        // Split the line into the different columns
        String[] columns = line.split("\t");
        // Set the thread ID
        threadSnapshot.setThreadID(Integer.parseInt(columns[0]));
        // Set the timestamp
        threadSnapshot.setTimestamp(Long.parseLong(columns[1]));
        // Set the stack trace
        String[] stackTrace = columns[2].split(",");
        threadSnapshot.setStackTrace(stackTrace);
        // Set the thread details
        threadSnapshot.setThreadDetails(columns[3]);
        // Return the ThreadSnapshot object
        return threadSnapshot;
    }
